function H.list(from, r)
    local l = {}
    local f = Workspace:FindFirstChild("MyPumpkins")
    for _, m in ipairs(f and f:GetChildren() or {}) do
        local ok, p = pcall(function() return m:GetPivot().Position end)
        if ok and (Vector3.new(p.X, 0, p.Z) - Vector3.new(from.X, 0, from.Z)).Magnitude < r then l[#l + 1] = p end
    end
    return l
end
function H.glide(b, ch, a, z, spd)
    local d = z - a
    local flat = Vector3.new(d.X, 0, d.Z)
    if flat.Magnitude < 1 then return end
    local dur = d.Magnitude / spd
    local t0 = os.clock()
    local cn = RunService.Heartbeat:Connect(function()
        if not (b.Parent and ch.Parent) then return end
        local p = a:Lerp(z, math.min(1, (os.clock() - t0) / dur))
        b:PivotTo(CFrame.lookAt(p, p + flat.Unit))
        ch.AssemblyLinearVelocity = flat.Unit * spd
    end)
    repeat task.wait() until os.clock() - t0 >= dur or not RUNNING or not G.seated()
    cn:Disconnect()
end
function H.rp(b)
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    local ex = { b, char() }
    for _, n in ipairs({ "MyPumpkins", "Traffic", "Police", "PlayerBuilds", "PartyDrops" }) do local f = Workspace:FindFirstChild(n) if f then ex[#ex + 1] = f end end
    rp.FilterDescendantsInstances = ex
    return rp
end
function H.go(b, ch, a, z, spd)
    local rp = H.rp(b)
    if not Workspace:Raycast(a, z - a, rp) then H.glide(b, ch, a, z, spd) return z end
    local hy = math.max(a.Y, z.Y) + 45
    local up = Vector3.new(a.X, hy, a.Z)
    local over = Vector3.new(z.X, hy, z.Z)
    H.glide(b, ch, a, up, spd)
    H.glide(b, ch, up, over, spd)
    H.glide(b, ch, over, z, spd)
    return z
end
function H.pass(b, ch, pos, tgt, spd)
    local rp = H.rp(b)
    local flat = Vector3.new(tgt.X - pos.X, 0, tgt.Z - pos.Z)
    local dir = flat.Magnitude > 1 and flat.Unit or Vector3.xAxis
    local best
    for k = 0, 7 do
        local a = math.atan2(dir.Z, dir.X) + math.pi + k * math.pi / 4
        local d = Vector3.new(math.cos(a), 0, math.sin(a))
        if not Workspace:Raycast(tgt, d * 16, rp) and not Workspace:Raycast(tgt, -d * 16, rp) then best = d break end
    end
    best = best or -dir
    local s0 = tgt + best * 14
    local s1 = tgt - best * 14
    H.go(b, ch, pos, s0, spd)
    H.glide(b, ch, s0, s1, 70)
    return s1
end
function H.hop()
    local ok, body = pcall(function() return game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Desc&limit=100") end)
    if not ok then say(L["Server list unavailable"]) return end
    local ok2, data = pcall(function() return HttpService:JSONDecode(body) end)
    local list = {}
    for _, sv in ipairs(ok2 and data and data.data or {}) do
        if sv.id ~= game.JobId and tonumber(sv.playing) and tonumber(sv.maxPlayers) and sv.playing < sv.maxPlayers - 1 then list[#list + 1] = sv.id end
    end
    if #list == 0 then say(L["No other servers found"]) return end
    if CONFIG.LOADER ~= "" and queue_on_teleport then pcall(queue_on_teleport, 'loadstring(game:HttpGet("' .. CONFIG.LOADER .. '"))()') end
    say(L["Hopping servers"])
    pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, list[math.random(1, #list)], lp) end)
end
