    if H.rate() >= H.cap() then H.status = L["Hourly pumpkin limit reached"] if on("h_hop") and os.clock() - (H.hopAt or 0) > 60 then H.hopAt = os.clock() H.hop() end return end
    if on("f_admin") and G.adminHere() then H.status = L["Paused · admin in server"] return end
    if G.busted() then return end
    if not G.seated() then if not on("f_farm") then H.status = L["Getting on bike"] F.mount() end return end
    local b = F.useBike()
    local ch = F.ch
    if not (b and ch) then return end
    local pos = ch.Position
    if #H.list(pos, 450) == 0 then
        H.status = L["Looking for pumpkins"]
        if on("h_hop") and os.clock() - H.lastSeen > 180 and os.clock() - (H.hopAt or 0) > 60 then H.hopAt = os.clock() H.hop() end
        return
    end
    H.lastSeen = os.clock()
    F.hold = L["Collecting pumpkins"]
    task.wait(0.3)
    local spd = 120
    for _ = 1, 10 do
        if not (RUNNING and on("h_farm") and G.seated()) or H.rate() >= H.cap() then break end
        local l = H.list(pos, 450)
        local best, bd
        for _, p in ipairs(l) do local dd = (p - pos).Magnitude if not bd or dd < bd then best, bd = p, dd end end
        if not best then break end
        local tgt = best + Vector3.new(0, 2.5, 0)
        H.status = L["Collecting pumpkins"]
        pos = H.pass(b, ch, pos, tgt, spd)
