function P.applyBoost()
    local b = F.bike or G.myBike()
    if not b then return end
    local base = F.base[b]
    if not base then base = { spd = b:GetAttribute("MaxSpeedKmh"), pop = b:GetAttribute("PopHeight") } F.base[b] = base end
    if base.spd then
        local want = on("b_speed") and base.spd * (val("b_speedv", 130) / 100) or base.spd
        if math.abs((b:GetAttribute("MaxSpeedKmh") or 0) - want) > 0.5 then b:SetAttribute("MaxSpeedKmh", want) end
    end
    for _, k in ipairs({ "LaunchAccel", "PowerPerKg", "TireGrip" }) do if base[k] == nil then base[k] = b:GetAttribute(k) or false end end
    if base.LaunchAccel then
        local m = on("b_accel") and (val("b_accelv", 140) / 100) or 1
        if math.abs((b:GetAttribute("LaunchAccel") or 0) - base.LaunchAccel * m) > 0.01 then b:SetAttribute("LaunchAccel", base.LaunchAccel * m) end
        if base.PowerPerKg and math.abs((b:GetAttribute("PowerPerKg") or 0) - base.PowerPerKg * m) > 0.5 then b:SetAttribute("PowerPerKg", base.PowerPerKg * m) end
    end
    if base.TireGrip then
        local m = on("b_grip") and (val("b_gripv", 140) / 100) or 1
        if math.abs((b:GetAttribute("TireGrip") or 0) - base.TireGrip * m) > 0.01 then b:SetAttribute("TireGrip", base.TireGrip * m) end
    end
    if base.pop then
        local want = on("b_pop") and base.pop * 1.8 or base.pop
        if math.abs((b:GetAttribute("PopHeight") or 0) - want) > 0.05 then b:SetAttribute("PopHeight", want) end
    end
end
