TP.NAMES = {} for _, s in ipairs(TP.SPOTS) do TP.NAMES[#TP.NAMES + 1] = s[1] end
function TP.ground(p)
    if not F.rp then F.params() end
    local r = Workspace:Raycast(p + Vector3.new(0, 6, 0), Vector3.new(0, -60, 0), F.rp)
    return r and r.Position or p
end
function TP.preload(p)
    task.spawn(function() pcall(function() lp:RequestStreamAroundAsync(p, 3) end) end)
    local t = os.clock()
    repeat
        if Workspace:Raycast(p + Vector3.new(0, 6, 0), Vector3.new(0, -60, 0), F.rp) then break end
        task.wait(0.15)
    until os.clock() - t > 3
    task.wait(0.2)
end
function TP.go(name)
    local spot
    for _, s in ipairs(TP.SPOTS) do if s[1] == name then spot = s end end
    if not spot then return end
    if on("f_farm") then Toggles.f_farm:SetValue(false) task.wait(0.4) end
    F.hold = "Teleporting"
    F.stop()
    local ok, err = pcall(function()
        local okp, p = pcall(spot[2])
        p = (okp and typeof(p) == "Vector3") and p or spot[3]
        if not F.rp then F.params() end
        TP.preload(p)
        if not F.mount() then say(L["Couldn't get on your bike"]) return end
        local b = G.myBike()
        local g = TP.ground(p)
        F.place(b, g + Vector3.new(0, 3, 0), Vector3.new(1, 0, 0))
        say(L["Teleported to "] .. name)
    end)
    if not ok then LOG("tp err", err) end
    F.hold = nil
    F.bike = nil
end
P.pauseOrig = nil
function P.antiPause(onP)
    if onP then
        if P.pauseOrig == nil then local ok, v = pcall(gethiddenproperty, Workspace, "StreamingIntegrityMode") P.pauseOrig = ok and v or false end
        pcall(sethiddenproperty, Workspace, "StreamingIntegrityMode", Enum.StreamingIntegrityMode.Disabled)
        pcall(function() GuiService:SetGameplayPausedNotificationEnabled(false) end)
    elseif P.pauseOrig ~= nil then
        if P.pauseOrig then pcall(sethiddenproperty, Workspace, "StreamingIntegrityMode", P.pauseOrig) end
        pcall(function() GuiService:SetGameplayPausedNotificationEnabled(true) end)
        P.pauseOrig = nil
    end
end
